import{_ as n,C as B,o as e,c as A,a7 as l,b as i,w as a,a as r,E as o,a8 as d}from"./chunks/framework.DmcojIVA.js";const f=JSON.parse('{"title":"高并发与高可用","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/high-concurrency-high-availability/index.md","filePath":"development/common/high-concurrency-high-availability/index.md","lastUpdated":1785428463000}'),h={name:"development/common/high-concurrency-high-availability/index.md"};function s(g,t,b,c,u,p){const E=B("Mermaid");return e(),A("div",null,[t[2]||(t[2]=l('<h1 id="gao-bing-fa-yu-gao-ke-yong" tabindex="-1">高并发与高可用 <a class="header-anchor" href="#gao-bing-fa-yu-gao-ke-yong" aria-label="Permalink to &quot;高并发与高可用&quot;">​</a></h1><p>高并发与高可用是大型在线系统的两项核心能力：</p><ul><li><strong>高并发（High Concurrency）</strong>：系统同时处理大量进行中请求的能力。</li><li><strong>高吞吐（High Throughput）</strong>：系统单位时间内完成有效工作的数量。</li><li><strong>高可用（High Availability）</strong>：系统在组件故障、流量变化和日常变更中持续提供服务的能力。</li></ul><p>高并发关注系统在负载上升时的容量和延迟，高可用关注系统在故障条件下的成功率和恢复能力。两者共同受 CPU、内存、网络、存储、下游依赖和故障余量约束。</p><h2 id="gao-bing-fa-yu-gao-ke-yong-de-guan-xi" tabindex="-1">高并发与高可用的关系 <a class="header-anchor" href="#gao-bing-fa-yu-gao-ke-yong-de-guan-xi" aria-label="Permalink to &quot;高并发与高可用的关系&quot;">​</a></h2><p>流量上升后，系统通常先出现资源利用率升高和请求排队，随后是尾延迟、超时与重试。如果没有限流、背压和降级，过载会使实例失联并减少有效容量，最终演变为可用性事故。</p>',6)),(e(),i(d,null,{default:a(()=>[o(E,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E4%B8%9A%E5%8A%A1%E6%B5%81%E9%87%8F%3Cbr%3E%E8%AF%B7%E6%B1%82%E9%80%9F%E7%8E%87%E4%B8%8E%E7%AA%81%E5%8F%91%22%5D%20--%3E%20B%5B%22%E5%B9%B6%E5%8F%91%E5%B7%A5%E4%BD%9C%3Cbr%3E%E8%BF%9E%E6%8E%A5%E3%80%81%E7%BA%BF%E7%A8%8B%E3%80%81%E5%8D%8F%E7%A8%8B%E3%80%81%E9%98%9F%E5%88%97%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E8%B5%84%E6%BA%90%E6%B6%88%E8%80%97%3Cbr%3ECPU%E3%80%81%E5%86%85%E5%AD%98%E3%80%81I%2FO%E3%80%81%E4%B8%8B%E6%B8%B8%E5%AE%B9%E9%87%8F%22%5D%0A%20%20%20%20C%20--%3E%20D%7B%22%E6%98%AF%E5%90%A6%E6%8E%A5%E8%BF%91%E9%A5%B1%E5%92%8C%EF%BC%9F%22%7D%0A%20%20%20%20D%20--%3E%7C%E5%90%A6%7C%20E%5B%22%E7%A8%B3%E5%AE%9A%E5%AE%8C%E6%88%90%E8%AF%B7%E6%B1%82%3Cbr%3E%E7%BB%B4%E6%8C%81%E5%BB%B6%E8%BF%9F%E4%B8%8E%E9%94%99%E8%AF%AF%E7%8E%87%22%5D%0A%20%20%20%20D%20--%3E%7C%E6%98%AF%7C%20F%5B%22%E6%8E%92%E9%98%9F%E4%B8%8E%E5%B0%BE%E5%BB%B6%E8%BF%9F%E4%B8%8A%E5%8D%87%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22%E8%B6%85%E6%97%B6%E3%80%81%E9%87%8D%E8%AF%95%E3%80%81%E5%AE%9E%E4%BE%8B%E5%A4%B1%E8%81%94%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22%E6%9C%89%E6%95%88%E5%AE%B9%E9%87%8F%E4%B8%8B%E9%99%8D%3Cbr%3E%E5%8F%AF%E7%94%A8%E6%80%A7%E5%8F%97%E6%8D%9F%22%5D%0A%20%20%20%20H%20--%3E%20C%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[r(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=l('<blockquote><p>参考：<a href="https://sre.google/sre-book/addressing-cascading-failures/" target="_blank" rel="noreferrer">Google SRE：Addressing Cascading Failures</a> 与 <a href="https://research.google/pubs/the-tail-at-scale/" target="_blank" rel="noreferrer">The Tail at Scale</a></p></blockquote><p>高可用设计同样依赖容量。为了容忍实例、节点或可用区故障，剩余副本必须有足够余量接管流量。正常状态下运行水位过高，即使部署了多个副本，故障转移后仍可能立即过载。</p><h2 id="he-xin-zhi-biao" tabindex="-1">核心指标 <a class="header-anchor" href="#he-xin-zhi-biao" aria-label="Permalink to &quot;核心指标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>含义</th><th>关注点</th></tr></thead><tbody><tr><td>QPS / TPS</td><td>每秒请求数或事务数</td><td>区分入口流量和成功完成量</td></tr><tr><td>并发数</td><td>某一时刻系统中的请求数</td><td>包括排队、计算和等待 I/O</td></tr><tr><td>吞吐量</td><td>单位时间完成的工作</td><td>同时观察错误和超时</td></tr><tr><td>Goodput</td><td>在时限内正确完成的有效工作</td><td>排除失败、超时和无效重试</td></tr><tr><td>延迟</td><td>单次操作从开始到完成的时间</td><td>观察 P50、P95、P99</td></tr><tr><td>可用性</td><td>满足成功条件的事件比例</td><td>以用户结果而非进程存活定义</td></tr><tr><td>容量</td><td>在目标 SLO 下可持续承载的最大负载</td><td>区分稳态、突发和压垮点</td></tr></tbody></table><p>系统即使接收了 10 万 QPS，如果多数请求最终超时，Goodput 依然很低。容量测试应以满足延迟和错误率目标的最大有效负载为结论。</p><h2 id="zong-ti-she-ji" tabindex="-1">总体设计 <a class="header-anchor" href="#zong-ti-she-ji" aria-label="Permalink to &quot;总体设计&quot;">​</a></h2>',6)),(e(),i(d,null,{default:a(()=>[o(E,{id:"mermaid-144",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20S%5B%22%E7%94%A8%E6%88%B7%E7%9B%AE%E6%A0%87%3Cbr%3E%E6%88%90%E5%8A%9F%E7%8E%87%E3%80%81%E5%BB%B6%E8%BF%9F%E3%80%81%E6%AD%A3%E7%A1%AE%E6%80%A7%22%5D%20--%3E%20M%5B%22SLI%20%2F%20SLO%22%5D%0A%20%20%20%20M%20--%3E%20C%5B%22%E5%AE%B9%E9%87%8F%E6%A8%A1%E5%9E%8B%3Cbr%3E%E5%B8%B8%E6%80%81%E3%80%81%E5%B3%B0%E5%80%BC%E3%80%81%E6%95%85%E9%9A%9C%E5%90%8E%22%5D%0A%20%20%20%20C%20--%3E%20A%5B%22%E6%9E%B6%E6%9E%84%E6%9C%BA%E5%88%B6%22%5D%0A%20%20%20%20A%20--%3E%20A1%5B%22%E6%89%A9%E5%B1%95%3Cbr%3E%E6%97%A0%E7%8A%B6%E6%80%81%E5%8C%96%E3%80%81%E5%88%86%E7%89%87%E3%80%81%E7%BC%93%E5%AD%98%22%5D%0A%20%20%20%20A%20--%3E%20A2%5B%22%E4%BF%9D%E6%8A%A4%3Cbr%3E%E9%99%90%E6%B5%81%E3%80%81%E8%83%8C%E5%8E%8B%E3%80%81%E9%99%8D%E7%BA%A7%22%5D%0A%20%20%20%20A%20--%3E%20A3%5B%22%E5%AE%B9%E9%94%99%3Cbr%3E%E5%86%97%E4%BD%99%E3%80%81%E9%9A%94%E7%A6%BB%E3%80%81%E6%95%85%E9%9A%9C%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20%20%20A1%20--%3E%20V%5B%22%E9%AA%8C%E8%AF%81%22%5D%0A%20%20%20%20A2%20--%3E%20V%0A%20%20%20%20A3%20--%3E%20V%0A%20%20%20%20V%20--%3E%20V1%5B%22%E8%B4%9F%E8%BD%BD%E6%B5%8B%E8%AF%95%22%5D%0A%20%20%20%20V%20--%3E%20V2%5B%22%E6%95%85%E9%9A%9C%E6%BC%94%E7%BB%83%22%5D%0A%20%20%20%20V%20--%3E%20V3%5B%22%E5%8F%91%E5%B8%83%E4%B8%8E%E6%81%A2%E5%A4%8D%E6%BC%94%E7%BB%83%22%5D%0A%20%20%20%20V1%20--%3E%20O%5B%22%E8%A7%82%E6%B5%8B%E4%B8%8E%E5%A4%8D%E7%9B%98%22%5D%0A%20%20%20%20V2%20--%3E%20O%0A%20%20%20%20V3%20--%3E%20O%0A%20%20%20%20O%20--%3E%20M%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[r(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=l('<blockquote><p>参考：<a href="https://sre.google/sre-book/embracing-risk/" target="_blank" rel="noreferrer">Google SRE：Embracing Risk</a> 与 <a href="https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/welcome.html" target="_blank" rel="noreferrer">AWS Well-Architected Reliability Pillar</a></p></blockquote><p>设计从用户目标开始：</p><ol><li>使用 SLI 和 SLO 定义成功率、延迟、正确性与数据恢复目标。</li><li>根据正常峰值和故障场景估算容量。</li><li>通过缓存、异步化、分片和水平扩展提高处理能力。</li><li>使用限流、背压、隔离、熔断和降级限制故障范围。</li><li>用负载测试、故障演练和恢复演练验证设计。</li></ol><h2 id="gao-bing-fa" tabindex="-1">高并发 <a class="header-anchor" href="#gao-bing-fa" aria-label="Permalink to &quot;高并发&quot;">​</a></h2><p>高并发设计主要处理容量、延迟和过载：</p><ul><li>使用 Little 定律估算请求速率、响应时间和在途请求数的关系；</li><li>降低单次请求的 CPU、内存、网络和存储成本；</li><li>使用缓存减少重复计算和回源请求；</li><li>使用消息队列把非关键工作移出同步请求链路；</li><li>通过无状态化、水平扩展和数据分片扩大总容量；</li><li>使用有界队列、并发限制、负载丢弃和重试预算保护 Goodput；</li><li>对 P99 延迟、热点分片和自动扩容滞后进行专项测试。</li></ul><p>详细内容见<a href="./high-concurrency.html">高并发系统设计</a>。</p><h2 id="gao-ke-yong" tabindex="-1">高可用 <a class="header-anchor" href="#gao-ke-yong" aria-label="Permalink to &quot;高可用&quot;">​</a></h2><p>高可用设计主要处理故障隔离和恢复：</p><ul><li>使用请求成功率、延迟、正确性等指标定义 SLO；</li><li>识别实例、节点、可用区、区域和共享依赖等故障域；</li><li>跨故障域部署冗余副本，并为故障转移保留容量；</li><li>区分启动、存活和就绪状态，避免错误健康检查放大故障；</li><li>明确数据复制、一致性、RPO、RTO 和备份恢复策略；</li><li>使用金丝雀发布、分批变更和优雅下线限制发布风险；</li><li>定期执行故障转移、数据恢复和大规模过载演练。</li></ul><p>详细内容见<a href="./high-availability.html">高可用系统设计</a>。</p><h2 id="she-ji-shi-li" tabindex="-1">设计示例 <a class="header-anchor" href="#she-ji-shi-li" aria-label="Permalink to &quot;设计示例&quot;">​</a></h2><p>以订单 API 为例，设计目标如下：</p><ul><li>正常流量 2,000 QPS，峰值 5,000 QPS；</li><li>99.9% 的合法请求成功；</li><li>99% 的请求在 300 ms 内完成；</li><li>单个实例、节点或可用区故障时仍满足核心 SLO；</li><li>已确认订单的数据恢复点目标（RPO）为 0。</li></ul><p>系统设计需要回答：</p><table tabindex="0"><thead><tr><th>问题</th><th>对应设计</th></tr></thead><tbody><tr><td>5,000 QPS、300 ms 下有多少在途请求</td><td>Little 定律、并发限制、连接池</td></tr><tr><td>单个可用区退出后能否承载峰值</td><td>故障容量、跨区负载均衡</td></tr><tr><td>库存服务变慢时如何保护订单服务</td><td>超时、隔离、熔断、降级</td></tr><tr><td>超出容量时如何处理请求</td><td>限流、有界队列、负载丢弃</td></tr><tr><td>数据库切换时如何处理未知结果</td><td>幂等键、重试语义、状态查询</td></tr><tr><td>如何确认系统仍满足目标</td><td>SLI、链路追踪、负载与故障测试</td></tr></tbody></table><h2 id="she-ji-yuan-ze" tabindex="-1">设计原则 <a class="header-anchor" href="#she-ji-yuan-ze" aria-label="Permalink to &quot;设计原则&quot;">​</a></h2><ul><li>先定义 SLO，再确定容量和架构。</li><li>容量以 Goodput 和尾延迟衡量，不以压垮点衡量。</li><li>队列用于吸收有限突发，不能解决长期容量不足。</li><li>自动扩容之前仍需要容量余量和过载保护。</li><li>副本必须跨故障域部署，并消除共享单点。</li><li>故障转移同时需要冗余副本和冗余容量。</li><li>降级、恢复和回滚路径必须定期执行。</li></ul><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>Google SRE Book：<a href="https://sre.google/sre-book/addressing-cascading-failures/" target="_blank" rel="noreferrer">Addressing Cascading Failures</a></li><li>Google SRE Book：<a href="https://sre.google/sre-book/embracing-risk/" target="_blank" rel="noreferrer">Embracing Risk</a></li><li>Jeffrey Dean、Luiz André Barroso：<a href="https://research.google/pubs/the-tail-at-scale/" target="_blank" rel="noreferrer">The Tail at Scale</a></li><li>AWS：<a href="https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/welcome.html" target="_blank" rel="noreferrer">Well-Architected Reliability Pillar</a></li><li>Google SRE Workbook：<a href="https://sre.google/workbook/implementing-slos/" target="_blank" rel="noreferrer">Implementing SLOs</a></li></ul>',20))])}const C=n(h,[["render",s]]);export{f as __pageData,C as default};
